# 定制健壮反序列化器，跨版本解决 _loss 缺失报错
class RobustUnpickler(pickle.Unpickler):
    def find_class(self, module, name):
        if module == '_loss' or module.endswith('._loss'):
            try:
                import sklearn._loss
                if hasattr(sklearn._loss, name):
                    return getattr(sklearn._loss, name)
            except Exception:
                pass
            try:
                import sklearn._loss._loss as sk_c
                if hasattr(sk_c, name):
                    return getattr(sk_c, name)
            except Exception:
                pass
            try:
                import sklearn._loss.loss as sk_l
                if hasattr(sk_l, name):
                    return getattr(sk_l, name)
            except Exception:
                pass
        return super().find_class(module, name)

@st.cache_resource
def load_model_assets():
    m_raw = base64.b64decode("")
    s_raw = base64.b64decode("")
    try:
        model = RobustUnpickler(io.BytesIO(m_raw)).load()
    except Exception:
        model = pickle.loads(m_raw)
    try:
        scaler = RobustUnpickler(io.BytesIO(s_raw)).load()
    except Exception:
        scaler = pickle.loads(s_raw)
    return model, scaler

